import argparse,csv,hashlib,html,json,shutil
from pathlib import Path

SETS=('confirmation','reproduction','confirmation_replay')
METHODS=('bloom','expert','reverse')
def canonical(value): return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True,allow_nan=False).encode()+b'\n'
def digest(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def load(path): return json.loads(path.read_text())
def write(path,value): path.write_bytes(canonical(value))
def number(x): return f'{x:,.0f}' if isinstance(x,(int,float)) else str(x)

def build(study,output,prefix):
    study,output=Path(study).resolve(),Path(output).resolve()
    output.mkdir(parents=True,exist_ok=True)
    analyses={s:load(study/f'results/{s}/analysis.json') for s in SETS}
    ledgers={s:load(study/f'results/{s}/campaign.json') for s in SETS}
    review_path='results/independent_reproduction_review/INDEPENDENT_REPRODUCTION_REVIEW.json'
    review=load(study/review_path)
    freeze=load(study/'protocol/FREEZE.json')
    assert review['G1_verdict']=='PASS' and review['all_frozen_source_hashes_match']
    assert all(analyses[s]['integrity']['exact_key_multiset'] for s in SETS)
    assert ledgers['confirmation']['deterministic_records_sha256']==ledgers['confirmation_replay']['deterministic_records_sha256']
    sources={}
    def evidence(path):
        source=study/path
        if path not in sources:
            sources[path]={'path':path,'sha256':digest(source),'bytes':source.stat().st_size}
        return path
    for path in ['protocol/PROTOCOL.md','protocol/FREEZE.json',review_path,'results/independent_reproduction_review/INTERPRETATION.md']:
        evidence(path)
    for s in SETS:
        for name in ['analysis.json','campaign.json','records.jsonl.gz']:
            evidence(f'results/{s}/{name}')
    for item in freeze['files']:
        actual=evidence(item['path'])
        assert sources[actual]['sha256']==item['sha256'],item['path']
    campaign_costs=[]
    for p in sorted((study/'development').rglob('campaign.json')):
        value=load(p);path=str(p.relative_to(study));evidence(path)
        campaign_costs.append({'id':path,'role':'development','world_executions':value['counts']['worlds'],'trials':value['counts']['trials'],'cpu_ns':value['campaign_cpu_ns'],'wall_ns':value['campaign_wall_ns'],'external_audit_cpu_ns_included':value['counts'].get('external_audit_cpu_ns',0),'replacement_cpu_ns_included':value['counts'].get('replacement_cpu_ns',0)})
    for s in SETS:
        value=ledgers[s]
        campaign_costs.append({'id':f'results/{s}/campaign.json','role':'replay_not_new_worlds' if s=='confirmation_replay' else s,'world_executions':value['counts']['worlds'],'trials':value['counts']['trials'],'cpu_ns':value['campaign_cpu_ns'],'wall_ns':value['campaign_wall_ns'],'external_audit_cpu_ns_included':value['counts']['external_audit_cpu_ns'],'replacement_cpu_ns_included':value['counts']['replacement_cpu_ns']})
    fresh=SETS[:2]
    combined={k:sum(analyses[s]['quality'][k] for s in fresh) for k in ['eligible_trials','completed_and_correct','boundary_trials','correct_boundary_refusals']}
    combined['required_artifact_rejections']=sum(analyses[s]['quality']['artifact_boundaries']['stale_or_withheld_trials'] for s in fresh)
    combined['correct_artifact_rejections']=sum(analyses[s]['quality']['artifact_boundaries']['correct_rejections'] for s in fresh)
    combined['conventional_replacements']=sum(analyses[s]['quality']['artifact_boundaries']['replacement_trials'] for s in fresh)
    combined['accepted_conventional_replacements']=sum(analyses[s]['quality']['artifact_boundaries']['replacement_accepted'] for s in fresh)
    missing={}
    for s in SETS:
        per_method={m:analyses[s]['methods'][m]['contexts']['missing_edge'] for m in METHODS}
        assert len({(x['false_safe_queries'],x['full_graph_queries']) for x in per_method.values()})==1
        sample=per_method['bloom']
        missing[s]={'unique_query_instances':sample['full_graph_queries'],'false_safe_unique_query_instances':sample['false_safe_queries'],'per_method_identical':True,'worlds':analyses[s]['worlds'],'interpretation':'Deliberately incomplete observed graph; exactness relative to that graph cannot establish completeness or real regression safety. Query counts are not independent graph samples.'}
    public=None
    if (study/'results/public-demo/summary.json').exists() and (study/'public_case/acceptance.json').exists():
        public_paths=['results/public-demo/summary.json','results/public-demo/index.html','results/public-demo/operator.json','results/public-demo/impact.json','results/public-demo/successor.json','results/public-demo/native/native_workflow_receipt.json','public_case/acceptance.json','public_case/source_receipt.json','public_case/audit_manifest.json','public_case/graph_audit.json.gz','public_case/case.json','public_case/README.md']
        for path in public_paths:evidence(path)
        demo=load(study/'results/public-demo/summary.json');acceptance=load(study/'public_case/acceptance.json');source=load(study/'public_case/source_receipt.json')
        expected=[{k:r[k] for k in ['affected','feasible','selected','cost']} for r in acceptance['query_results']]
        assert expected==demo['successor']['outputs']
        public={'role':'practical_public_manifest_acceptance_excluded_from_scientific_inference','counts':acceptance['counts'],'acceptance_status':acceptance['status'],'all_demo_outputs_match_independent_acceptance':True,'chosen_operator':demo['operator'],'native_stages_completed':len(demo['native']['completed_stages']),'native_status':demo['native']['status'],'restoration':demo['native']['restoration'],'cpu_ns':demo['native']['total_cpu_ns'],'wall_ns':demo['native']['total_wall_ns'],'cost_scope':demo['native']['cost_scope'],'source_receipt':source,'boundaries':demo['boundaries'],'real_regression_safety':'not_established','actual_tests_executed':0,'coverage_cost_unit':acceptance['coverage_cost_unit'],'sources':public_paths}
    summary={'schema':'bloom-poststudy-publication-summary/v1','study':'BLOOM infinity: verified capacity, conditional value','edition':freeze['edition'],'derived_report_only':True,'frozen_scientific_sources_modified':False,'intended_bundle_directory':'reporting/evidence-index','link_prefix':prefix,'preregistration':{'frozen_at_utc':freeze['frozen_at_utc'],'freeze_sha256':digest(study/'protocol/FREEZE.json'),'frozen_files':len(freeze['files']),'protocol_sha256':digest(study/'protocol/PROTOCOL.md'),'public_registration_comment':'https://github.com/MontrealAI/AGI-Alpha-Agent-v0/issues/4850#issuecomment-6378518568'},'sampling':{'unique_confirmatory_worlds':analyses['confirmation']['worlds'],'unique_independent_reproduction_worlds':analyses['reproduction']['worlds'],'unique_scientific_worlds':sum(analyses[s]['worlds'] for s in fresh),'fresh_scientific_trial_executions':sum(analyses[s]['trials'] for s in fresh),'replayed_worlds_not_new_samples':analyses['confirmation_replay']['worlds'],'replay_trial_executions_not_new_samples':analyses['confirmation_replay']['trials'],'actual_three_campaign_trial_executions':sum(analyses[s]['trials'] for s in SETS),'statistical_unit':'graph world, not query, trial, timing repeat or stage','development_worlds_excluded':sum(x['world_executions'] for x in campaign_costs if x['role']=='development'),'public_practical_case_excluded':True},'gate_history':{'original_analysis_gates':{s:analyses[s]['gates'] for s in SETS},'later_independent_G1_closure':{'verdict':review['G1_verdict'],'source':review_path,'source_sha256':digest(study/review_path),'deterministic_records_identical':review['confirmation_comparison']['original_records'],'cases_identical':len(review['confirmation_comparison']['case_checks']),'operators_identical':len(review['confirmation_comparison']['operator_checks']),'deterministic_stream_sha256':review['confirmation_comparison']['independently_recomputed_sha256'],'scope':'same-session independent execution; exact deterministic equality excludes timings'},'publication_verdict':{'G1':'PASS_AFTER_INDEPENDENT_REPLAY','G2':'PASS','G3':'FAIL','G4':'FAIL','G5':'INCOMPLETE_COSTS_AND_DEMAND'},'original_analysis_files_unchanged':True},'datasets':{s:{'worlds':analyses[s]['worlds'],'trials':analyses[s]['trials'],'quality':analyses[s]['quality'],'competitive_contrasts':analyses[s]['competitive_contrasts'],'artifact_dependence':analyses[s]['artifact_dependence'],'primary_mean_cpu_seconds':analyses[s]['primary_mean_cpu_seconds'],'stable_operator_choices':{m:analyses[s]['methods'][m]['stable_operator_choices'] for m in METHODS},'failed_constructions':{m:analyses[s]['methods'][m]['failed_constructions_all_contexts'] for m in METHODS},'unsafe_receiver_proof_ablation':analyses[s]['unsafe_receiver_proof_ablation'],'no_construction_ablation':analyses[s]['no_construction_ablation'],'source':f'results/{s}/analysis.json'} for s in SETS},'fresh_quality_combined_descriptive_only':combined,'negative_findings':{'competitive_advantage_not_established':True,'prespecified_20_percent_receiver_benefit_not_established':True,'unsafe_fresh_trials':sum(analyses[s]['unsafe_receiver_proof_ablation']['trials'] for s in fresh),'unsafe_fresh_false_acceptances':sum(analyses[s]['unsafe_receiver_proof_ablation']['false_acceptances'] for s in fresh),'missing_edge_challenge':missing,'stable_synthetic_policy_switching_not_demonstrated':'BLOOM and expert both chose SCC in all 48 original stable worlds; fallback is exercised in declared robustness contexts.'},'cost_ledger':{'measured_complete_campaigns':campaign_costs,'measured_campaign_cpu_ns_once':sum(x['cpu_ns'] for x in campaign_costs),'measured_campaign_wall_ns_once':sum(x['wall_ns'] for x in campaign_costs),'external_audit_subset_cpu_ns_already_included':sum(x['external_audit_cpu_ns_included'] for x in campaign_costs),'replacement_subset_cpu_ns_already_included':sum(x['replacement_cpu_ns_included'] for x in campaign_costs),'counting_rule':'Sum each top-level campaign receipt exactly once. Do not add cumulative research_budget values, nested prior_receipts, external-audit subsets, per-arm replacement attribution, or duplicated review copies. Replay compute is real cost but not new scientific worlds.','public_demo_native_cpu_ns_separate':public['cpu_ns'] if public else None,'public_demo_native_wall_ns_separate':public['wall_ns'] if public else None,'public_demo_cost_scope':public['cost_scope'] if public else None,'actual_cash_revenue':0,'firm_offers':0,'independently_supported_demand':0,'observed_new_explicit_paid_resource_charges':0,'physical_detector_acquisitions':0,'hypothetical_willingness_to_pay':'not elicited','actual_full_monetary_cost':'incomplete','unknown_cost_categories':analyses['confirmation']['economics']['unknown_costs'],'unmeasured_or_separately_scoped_work':['authoring and model/service execution','initial developer timings without complete campaign receipts','other native smoke checks and integration work','reporting and typesetting','future maintenance','hardware ownership and power'],'modeled_sensitivity_scenarios':analyses['confirmation']['economics']['sensitivity'],'synthetic_coverage_weights':'declared task inputs, not measured test durations, money, revenue or opportunity costs','credible_cpu_alternative':'measured conventional solution to the same accepted workload; no demand or transaction evidence'},'public_practical_demo':public,'sources':sources,'claim_scope':'Implemented and measured local exact supplied-graph semantics; conditional modeled monetary conversion; no novel graph-algorithm, general intelligence, real regression safety, commercial superiority or autonomous wealth claim.'}
    claims=[]
    def claim(cid,classification,text,source,pointer,verdict='SUPPORTED_WITH_STATED_SCOPE',limit=''):
        claims.append({'claim_id':cid,'classification':classification,'claim':text,'verdict':verdict,'source_path':source,'json_pointer':pointer,'source_sha256':sources[evidence(source)]['sha256'],'additional_source_paths':'','limitation':limit})
    claim('C001','measured',f"{summary['sampling']['unique_scientific_worlds']} unique scientific worlds comprise 48 confirmation and 24 fresh reproduction worlds; 48 replayed worlds add no independent sample.",'results/confirmation/campaign.json','/case_manifest',limit='The reproduction case manifest is separately preserved; trial and query counts are not independent samples.')
    claim('C002','measured','All 2,544 deterministic confirmation records, 48 case files and 480 operator files reproduce exactly.',review_path,'/confirmation_comparison',limit='Timing excluded; same-session independent execution, not organizational independence.')
    claim('C003','provenance','The original analysis G1 PENDING status is preserved; the later independent receipt closes G1 as PASS.',review_path,'/G1_verdict')
    for s,short in [('confirmation','C'),('reproduction','R')]:
        a=analyses[s];path=f'results/{s}/analysis.json'
        claim(short+'010','measured',f"{a['quality']['completed_and_correct']}/{a['quality']['eligible_trials']} eligible trials resolved exactly; {a['quality']['correct_boundary_refusals']}/{a['quality']['boundary_trials']} boundary refusals were correct.",path,'/quality',limit='Exactness relative to supplied graphs and coverage, not real regression safety.')
        for comparator,cid in [('expert','020'),('reverse','021')]:
            v=a['competitive_contrasts'][comparator]
            claim(short+cid,'measured',f"BLOOM/{comparator} CPU ratio {v['geometric_mean_ratio']:.9f}, adjusted interval [{v['ci_lower']:.9f},{v['ci_upper']:.9f}]; upper bound misses 0.90.",path,f'/competitive_contrasts/{comparator}','PRACTICAL_ADVANTAGE_NOT_ESTABLISHED','Median runs within each graph, then paired graph inference; nominal 98.333333% percentile-bootstrap intervals.')
        v=a['artifact_dependence']
        claim(short+'030','measured',f"Retained/withheld receiver CPU ratio {v['geometric_mean_ratio']:.9f}, adjusted interval [{v['ci_lower']:.9f},{v['ci_upper']:.9f}]; upper bound misses 0.80.",path,'/artifact_dependence','PRESPECIFIED_EFFECT_NOT_ESTABLISHED','Receiver-only controlled effect; report predecessor costs separately; point improvement is not threshold passage.')
        unsafe=a['unsafe_receiver_proof_ablation']
        claim(short+'040','negative',f"Receiver-proof-disabled diagnostic falsely accepted {unsafe['false_acceptances']}/{unsafe['trials']} cases.",path,'/unsafe_receiver_proof_ablation',limit='Diagnostic only; all other output checks remain; not an operational default.')
        m=missing[s]
        claim(short+'041','negative',f"Missing-edge challenge omitted real affected apps on {m['false_safe_unique_query_instances']}/{m['unique_query_instances']} unique query instances; all 3 methods agree.",path,'/methods/bloom/contexts/missing_edge',limit='Deliberately incomplete observation outside supplied-graph guarantee; do not triple-count method repeats or infer independent query samples.')
    claim('C050','negative','BLOOM and expert both chose SCC for 48/48 stable confirmatory worlds. Novel selective-policy advantage is not demonstrated.','results/confirmation/analysis.json','/methods/bloom/stable_operator_choices')
    claim('C060','measured','All 144 conventional replacement trials accepted the replacement without fallback; origin-exclusive capability necessity is not established.','results/confirmation/analysis.json','/quality/artifact_boundaries')
    claim('E001','observed','Actual cash revenue, firm offers and independently supported demand are zero in the recorded study.','results/confirmation/analysis.json','/economics',limit='No customer transaction or customer validation was performed.')
    claim('E002','modeled','CPU-dollar and engineering-hour sensitivities are conditional assumptions, not observed fees, complete cost or proven commerce.','results/confirmation/analysis.json','/economics/sensitivity','FULL_MONETARY_COST_INCOMPLETE','Unknown authoring, model/service, hardware and maintenance costs remain explicit.')
    if public:
        claim('P001','measured',f"Public lock-map fixture has {public['counts']['nodes']} nodes, {public['counts']['edges']} edges and {public['counts']['queries']} fixed queries; demo answers match independent acceptance.",'public_case/acceptance.json','/query_results',limit='Static declarations; 16 unresolved optional peers; coverage weights synthetic; no real tests executed.')
        claim('P002','implemented','The actual local Alpha dispatcher completed 7 stages; restoration is stopped with zero active proofs and grants.','results/public-demo/native/native_workflow_receipt.json','/restoration',limit='Public test signing material; no external submission, settlement, deployment or cross-repository task admission.')
    for entry in claims:
        if entry['claim_id']=='C001': entry['additional_source_paths']='results/reproduction/campaign.json'
        if entry['claim_id']=='C003': entry['additional_source_paths']='results/confirmation/analysis.json'
        if entry['claim_id']=='E001': entry['additional_source_paths']='results/confirmation/campaign.json'
        if entry['claim_id']=='P001': entry['additional_source_paths']='results/public-demo/summary.json'
    summary['sources']=sources
    summary['claims']=claims
    write(output/'publication_summary.json',summary)
    with (output/'CLAIMS.csv').open('w',newline='') as f:
        writer=csv.DictWriter(f,fieldnames=list(claims[0]));writer.writeheader();writer.writerows(claims)
    def link(path,label=None):return f'[{label or path}]({prefix}{path})'
    lines=['# BLOOM evidence map','','This index is a post-study description of immutable measurements. It does not edit the frozen source or promote a pending original gate in place.','','## What the record establishes','',f"- **{summary['sampling']['unique_scientific_worlds']} unique scientific worlds**: 48 confirmation + 24 fresh reproduction. 48 worlds are additionally replayed; replay compute is real cost, not new statistical evidence.",'- **G1 PASS in a later independent closure**; original analysis files retain `PENDING_INDEPENDENT_REPLAY`.',f"- **G2 PASS**: fresh datasets together resolve {combined['completed_and_correct']}/{combined['eligible_trials']} eligible trials exactly and {combined['correct_boundary_refusals']}/{combined['boundary_trials']} boundary cases correctly.",'- **G3 FAIL, G4 FAIL**: no declared 10% competitive win or established 20% receiver advantage. See exact paired intervals; a favorable point estimate is insufficient.','- **G5 incomplete**: no actual revenue, firm offer or demand validation; unknown full monetary costs remain explicit.','','## Start here','',link('protocol/PROTOCOL.md','Frozen protocol')+' · '+link('protocol/FREEZE.json','Source freeze')+' · '+link(review_path,'Independent replay closure'),'','| Evidence | Purpose |','| --- | --- |']
    for s in SETS:
        lines.append(f"| {link(f'results/{s}/analysis.json',s+' analysis')} | Exact outcomes, intervals and original gate states |")
        lines.append(f"| {link(f'results/{s}/records.jsonl.gz',s+' raw records')} | Every trial, decision, failure and phase timing |")
        lines.append(f"| {link(f'results/{s}/campaign.json',s+' ledger')} | One top-level campaign cost and manifests |")
    if public:
        lines.extend([f"| {link('results/public-demo/index.html','Public-manifest local walkthrough')} | Actual 7-stage native demonstration, conventional reverse index |",f"| {link('public_case/acceptance.json','Independent public acceptance')} | 1,136 nodes, 2,000 edges, 17 queries and explicit unresolved records |",f"| {link('public_case/source_receipt.json','Pinned source receipts')} | Exact public Git commits, Git blobs and SHA-256 |"])
    lines+=['','## Claim-to-evidence mapping','','`CLAIMS.csv` and `publication_summary.json` bind every major claim to a source file, JSON pointer and SHA-256. The confidence intervals and practical thresholds are copied from the frozen analyses, not recalculated here.','','## Negative findings are first-class evidence','',f"The unsafe receiver-proof ablation falsely accepts {summary['negative_findings']['unsafe_fresh_false_acceptances']}/{summary['negative_findings']['unsafe_fresh_trials']} fresh cases. The missing-edge challenge produces 1,657/2,176 false-safe query instances in confirmation and 897/1,088 in fresh reproduction, identically for all 3 methods. These are deliberately incomplete observations, outside the supplied-graph guarantee, and must not be counted 3 times or interpreted as independent query samples.",'','## Cost reconciliation','','Sum each top-level campaign once. The completed measured campaigns, including development and the repeated confirmation computation, consume '+f"{summary['cost_ledger']['measured_campaign_cpu_ns_once']/1e9:.9f} CPU seconds"+'. External-audit and replacement-production fields are included subsets; nested cumulative budgets and duplicated review receipts are not additional costs. The public native demo is separately measured. Initial incomplete measurements, authoring, model/service fees, hardware ownership, additional integration work, reporting and future maintenance prevent a complete monetary claim.','','## Archive layout','','Place this directory at `reporting/evidence-index/` inside the complete study bundle. Links use `../../` to reach the retained protocol, sources and results. The generator accepts `--link-prefix` for a deliberately different bundle location. No network or server is required to inspect the HTML summary. Raw gzip evidence can be opened with ordinary gzip/Python tools.','','## Regenerate','','```sh','python3 reporting/build_evidence_index.py --study-root . --output reporting/evidence-index --link-prefix ../../','```','']
    (output/'EVIDENCE_MAP.md').write_text('\n'.join(lines))
    create_html(output,summary,prefix)
    manifest={'schema':'bloom-derived-evidence-index-manifest/v1','generator_sha256':digest(Path(__file__)),'files':[{'path':name,'sha256':digest(output/name),'bytes':(output/name).stat().st_size} for name in ['publication_summary.json','CLAIMS.csv','EVIDENCE_MAP.md','evidence.html']],'scientific_sources_unchanged':True,'intended_bundle_directory':'reporting/evidence-index'}
    write(output/'INDEX_MANIFEST.json',manifest)
    print(json.dumps({'output':str(output),'claims':len(claims),'sources':len(sources),'unique_scientific_worlds':summary['sampling']['unique_scientific_worlds'],'fresh_trials':summary['sampling']['fresh_scientific_trial_executions'],'replay_trials':summary['sampling']['replay_trial_executions_not_new_samples'],'known_campaign_cpu_s':summary['cost_ledger']['measured_campaign_cpu_ns_once']/1e9,'public_demo_included':bool(public),'manifest_sha256':digest(output/'INDEX_MANIFEST.json')}))

def create_html(output,data,prefix):
    payload=json.dumps(data,ensure_ascii=True,separators=(',',':')).replace('</','<\\/')
    template='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>BLOOM ∞ · Inspect the evidence</title><style>
:root{color-scheme:dark;--bg:#0a0713;--panel:#151022;--line:#382d4a;--ink:#f5f1ff;--muted:#b6abc9;--violet:#bd9bff;--mint:#8ce4c0;--amber:#f1c487}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 system-ui,-apple-system,sans-serif}a{color:#cbb5f4;text-underline-offset:3px}main{max-width:1240px;margin:auto;padding:38px 25px 70px}header{position:relative;padding:44px 0 35px;border-bottom:1px solid var(--line);background:radial-gradient(ellipse at 75% 20%,#56328655,transparent 60%)}.eyebrow{font-size:.78rem;letter-spacing:.2em;color:var(--violet)}h1{font-size:clamp(3.3rem,10vw,6.5rem);font-weight:550;line-height:1.05;letter-spacing:-.05em;margin:16px 0}h2{font-size:clamp(1.8rem,4vw,2.8rem);font-weight:500;line-height:1.15;margin:0 0 16px}h3{font-size:1.1rem;font-weight:500}.lede{max-width:870px;font-size:1.22rem;color:#d8cee7}.muted,small{color:var(--muted)}.nav{display:flex;gap:20px;flex-wrap:wrap;margin:25px 0 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;margin:30px 0}.card,section{background:var(--panel);border:1px solid var(--line);border-radius:15px;padding:23px}.card .big{font-size:2rem;color:var(--mint);line-height:1.2;margin:8px 0}section{margin:22px 0}.status{font-size:.78rem;letter-spacing:.07em;display:inline-block;border:1px solid var(--line);border-radius:99px;padding:4px 11px;margin-bottom:10px}.pass{color:var(--mint)}.fail{color:var(--amber)}.gates{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:12px}.gate{padding:17px;background:#1c142a;border-radius:10px}.notice{border-left:3px solid var(--amber);padding:12px 17px;background:#2a1d2055}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:.91rem}th,td{vertical-align:top;text-align:left;padding:13px 10px;border-bottom:1px solid var(--line)}th{font-weight:500;color:#d7c5ef}select,input,button{border:1px solid #5a466e;border-radius:7px;background:#24182f;color:var(--ink);font:inherit;padding:10px 13px}input{width:min(100%,650px)}select{margin:12px 0 18px;max-width:100%}code{font-size:.8rem;word-break:break-all;color:#d9c6fa}details{margin-top:16px}summary{cursor:pointer;color:var(--violet)}.claims td:nth-child(1){min-width:70px}.claims td:nth-child(2){min-width:350px}.claims td:nth-child(3){min-width:225px}.links{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:12px}.linkbox{border:1px solid var(--line);padding:14px;border-radius:9px}footer{font-size:.86rem;color:var(--muted);margin-top:30px}a:focus-visible,input:focus-visible,select:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--mint);outline-offset:4px}.mono{font-variant-numeric:tabular-nums}.nowrap{white-space:nowrap}@media(max-width:600px){main{padding:18px 14px 45px}section,.card{padding:16px}table{font-size:.85rem}.lede{font-size:1.05rem}}
</style></head><body><main><header><div class="eyebrow">AGI ALPHA · TRANSFORMATIONAL INTELLIGENCE ∞ · SUCCESSOR Ω</div><h1>BLOOM ∞</h1><p class="lede">Verified capacity. Transparent verdict.<br>A portable impact capability survives exact revalidation. The declared advantage still has to be earned.</p><p class="muted">Post-study evidence browser · immutable protocol and measurements · no new scientific analysis</p><nav class="nav" aria-label="Evidence sections"><a href="#verdict">Verdict</a><a href="#results">Paired results</a><a href="#negatives">Failures</a><a href="#costs">Costs</a><a href="#public">Useful now</a><a href="#claims">Claim ledger</a></nav></header><div class="grid" id="metrics"></div><section id="verdict"><h2>The measured verdict</h2><div class="gates" id="gates"></div><p class="notice">Original analysis files retain G1 “pending.” A later, separately preserved independent replay closes G1. G3 and G4 remain failed hypotheses; G5 remains incomplete.</p></section><section id="results"><h2>Every comparison keeps its denominator.</h2><label for="dataset">Evidence set</label><br><select id="dataset"><option value="confirmation">Original confirmation · 48 worlds</option><option value="reproduction">Fresh reproduction · 24 worlds</option><option value="confirmation_replay">Confirmation replay · same 48 worlds</option></select><div class="scroll"><table><thead><tr><th>Contrast</th><th>CPU ratio</th><th>Adjusted interval</th><th>Required upper bound</th><th>Verdict</th></tr></thead><tbody id="contrasts"></tbody></table></div><p class="muted">Ratios below 1 favor the numerator. Each graph contributes the median of three complete runs. Intervals are the frozen 98.333333% paired-world percentile bootstrap, with nominal multiplicity adjustment and approximate coverage. Receiver timing is separate from complete predecessor-plus-successor cost.</p><div id="quality"></div></section><section id="negatives"><h2>Failures remain visible.</h2><div class="grid" id="negative-cards"></div><p class="notice">The missing-edge challenge deliberately hides real dependencies. Every method is exact on the supplied graph and still misses affected applications in the complete graph. A valid digest or exact graph proof cannot recover evidence that was never observed.</p><p class="muted">BLOOM and the expert conventional policy both selected SCC in all 48 stable confirmatory worlds. This study does not demonstrate novel algorithm selection. Conventional replacement succeeds; origin-exclusive necessity is not established.</p></section><section id="costs"><h2>Count each resource once.</h2><div id="cost-summary"></div><div class="scroll"><table><thead><tr><th>Measured campaign</th><th>Trials</th><th>CPU seconds</th><th>Wall seconds</th></tr></thead><tbody id="cost-rows"></tbody></table></div><p class="notice">External audit and replacement construction are included subsets of campaign CPU. Do not add nested cumulative budgets or duplicate review copies. Replayed computation is a real resource cost and contributes no new independent worlds.</p><p>Revenue: 0. Firm offers: 0. Validated demand: 0. Full monetary cost: incomplete. CPU prices and engineering-hour scenarios are assumptions; synthetic coverage weights are task inputs.</p><details><summary>Known omissions and conditional modeled economics</summary><pre id="economic-detail" style="white-space:pre-wrap;word-break:break-word"></pre></details></section><section id="public"><h2>A concrete public maintenance question.</h2><div id="public-detail"></div></section><section id="claims"><h2>Trace each claim to its bytes.</h2><label for="filter">Filter claims</label><br><input id="filter" type="search" placeholder="Try: replacement, costs, missing-edge" autocomplete="off"><div class="scroll"><table class="claims"><thead><tr><th>ID</th><th>Claim and boundary</th><th>Exact source</th></tr></thead><tbody id="claim-rows"></tbody></table></div></section><section><h2>Open the complete evidence.</h2><div class="links" id="links"></div><details><summary>Freeze identity and source verification</summary><pre id="freeze-detail" style="white-space:pre-wrap;word-break:break-word"></pre></details><p><a href="publication_summary.json">Machine-readable summary</a> · <a href="CLAIMS.csv">Claim ledger CSV</a> · <a href="EVIDENCE_MAP.md">Evidence map</a> · <a href="INDEX_MANIFEST.json">Index hashes</a></p></section><footer>Local experimental research. Supplied-graph exactness is not complete real dependency knowledge, regression safety, commercial viability or external execution authority. Public test signing material establishes no production identity. Existing project publications remain distinct.</footer></main><script id="data" type="application/json">__DATA__</script><script>
const d=JSON.parse(document.getElementById('data').textContent),prefix=d.link_prefix;const esc=x=>String(x).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));const fmt=x=>Number(x).toLocaleString('en-US');const a=(path,label)=>'<a href="'+esc(prefix+path)+'">'+esc(label||path)+'</a>';const s=d.sampling,q=d.fresh_quality_combined_descriptive_only;
document.getElementById('metrics').innerHTML=[['Unique scientific worlds',s.unique_scientific_worlds,'48 confirmation + 24 fresh reproduction'],['Fresh trial executions',s.fresh_scientific_trial_executions,'Trials are not independent worlds'],['Exact eligible resolutions',q.completed_and_correct+'/'+q.eligible_trials,'Confirmation+fresh reproduction'],['Exact replayed records',2544,'Same worlds; no sample inflation']].map(x=>'<article class="card"><div class="muted">'+esc(x[0])+'</div><div class="big mono">'+esc(x[1])+'</div><small>'+esc(x[2])+'</small></article>').join('');
document.getElementById('gates').innerHTML=[['G1','PASS','Exact independent replay','pass'],['G2','PASS','Qualified output and boundaries','pass'],['G3','FAIL','Required 10% comparative gain','fail'],['G4','FAIL','Required 20% receiver gain','fail'],['G5','INCOMPLETE','Full costs and demand','fail']].map(x=>'<div class="gate"><span class="status '+x[3]+'">'+x[0]+' · '+x[1]+'</span><div>'+esc(x[2])+'</div></div>').join('');
function show(){const name=document.getElementById('dataset').value,v=d.datasets[name],rows=[['BLOOM / expert conventional',v.competitive_contrasts.expert],['BLOOM / reverse conventional',v.competitive_contrasts.reverse],['Retained / withheld receiver',v.artifact_dependence]];document.getElementById('contrasts').innerHTML=rows.map(x=>'<tr><td>'+esc(x[0])+'</td><td class="mono">'+x[1].geometric_mean_ratio.toFixed(6)+'</td><td class="mono nowrap">['+x[1].ci_lower.toFixed(6)+', '+x[1].ci_upper.toFixed(6)+']</td><td>&lt;'+x[1].practical_threshold.toFixed(2)+'</td><td class="fail">Not established</td></tr>').join('');document.getElementById('quality').innerHTML='<p><b>'+fmt(v.quality.completed_and_correct)+'/'+fmt(v.quality.eligible_trials)+'</b> eligible trials resolve exactly; <b>'+fmt(v.quality.correct_boundary_refusals)+'/'+fmt(v.quality.boundary_trials)+'</b> boundary refusals are correct. '+a(v.source,'Open original analysis')+'</p>';}document.getElementById('dataset').onchange=show;show();
const n=d.negative_findings;document.getElementById('negative-cards').innerHTML=[['Unsafe receiver-proof ablation',n.unsafe_fresh_false_acceptances+'/'+n.unsafe_fresh_trials,'Fresh false acceptances; diagnostic only'],['Missing edges · confirmation','1657/2176','Unique query instances; all methods agree'],['Missing edges · fresh reproduction','897/1088','Outside supplied-graph guarantee']].map(x=>'<div class="card"><div>'+esc(x[0])+'</div><div class="big fail">'+esc(x[1])+'</div><small>'+esc(x[2])+'</small></div>').join('');
const c=d.cost_ledger;document.getElementById('cost-summary').innerHTML='<p><b>'+ (c.measured_campaign_cpu_ns_once/1e9).toFixed(9)+'CPU seconds</b> across the separately listed completed campaigns, including development and replay. This is a measured subtotal, not full monetary research cost.</p>';document.getElementById('cost-rows').innerHTML=c.measured_complete_campaigns.map(x=>'<tr><td>'+a(x.id,x.role)+'</td><td>'+fmt(x.trials)+'</td><td class="mono">'+(x.cpu_ns/1e9).toFixed(6)+'</td><td class="mono">'+(x.wall_ns/1e9).toFixed(6)+'</td></tr>').join('');document.getElementById('economic-detail').textContent=JSON.stringify({unknown_costs:c.unknown_cost_categories,omitted_or_separate:c.unmeasured_or_separately_scoped_work,conditional_scenarios:c.modeled_sensitivity_scenarios},null,2);
const p=d.public_practical_demo;document.getElementById('public-detail').innerHTML=p?'<p>The two pinned public package-lock maps contain <b>'+fmt(p.counts.nodes)+' nodes and '+fmt(p.counts.edges)+' edges</b>. All '+p.counts.queries+'fixed queries match independent acceptance. The conventional <b>'+esc(p.chosen_operator.strategy)+'</b>operator feeds a distinct finite coverage successor through all'+p.native_stages_completed+'native stages.</p><p>'+a('results/public-demo/index.html','Open the local walkthrough')+' · '+a('public_case/acceptance.json','Inspect independent acceptance')+' · '+a('public_case/README.md','Read source and coverage limits')+'</p><p class="notice">'+p.counts.unresolved_records+'optional peer declarations remain unresolved. Coverage labels are synthetic; no real tests are executed. Restored history is stopped, with zero active proofs and grants. Native integration does not establish external four-repository execution.</p>':'<p>Public demonstration receipt not present in this index.</p>';
function claims(){const term=document.getElementById('filter').value.toLowerCase();document.getElementById('claim-rows').innerHTML=d.claims.filter(x=>JSON.stringify(x).toLowerCase().includes(term)).map(x=>'<tr><td><b>'+esc(x.claim_id)+'</b><br><small>'+esc(x.classification)+'</small></td><td>'+esc(x.claim)+'<p class="muted">'+esc(x.limitation)+'</p></td><td>'+a(x.source_path,'Open source')+'<br><code>'+esc(x.json_pointer)+'</code><details><summary>SHA-256</summary><code>'+esc(x.source_sha256)+'</code></details></td></tr>').join('');}document.getElementById('filter').oninput=claims;claims();
const links=[['protocol/PROTOCOL.md','Frozen protocol'],['protocol/FREEZE.json','Pre-execution freeze'],['results/confirmation/records.jsonl.gz','Every original confirmatory trial'],['results/reproduction/records.jsonl.gz','Every fresh reproduction trial'],['results/confirmation_replay/records.jsonl.gz','Every repeated confirmation trial'],['results/independent_reproduction_review/INDEPENDENT_REPRODUCTION_REVIEW.json','Independent deterministic comparison'],['results/confirmation/cases/20001.json','A complete confirmatory input'],['results/confirmation/operators/20001-bloom-stable.json','Its qualified portable operator'],['independent/reference.py','Independent checkers and conventional policy']];document.getElementById('links').innerHTML=links.map(x=>'<div class="linkbox">'+a(x[0],x[1])+'</div>').join('');document.getElementById('freeze-detail').textContent=JSON.stringify({preregistration:d.preregistration,gate_history:d.gate_history},null,2);
</script></body></html>'''
    (output/'evidence.html').write_text(template.replace('__DATA__',payload))

if __name__=='__main__':
    parser=argparse.ArgumentParser(description='Derive a publication evidence index from frozen, completed BLOOM receipts. No scientific execution.')
    parser.add_argument('--study-root',required=True);parser.add_argument('--output',required=True);parser.add_argument('--link-prefix',default='../../')
    args=parser.parse_args();build(args.study_root,args.output,args.link_prefix)
